INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1016, '数学', '三年级', 'fill', 3, '{"stem": "填空(6)：要使□08×4的积是三位数，□里最大填（ ）；要使360×□的积是四位数，□里最小填（ ）。"}', '2, 3', '208×4=832(三位数), 308×4=1232(四位数)→最大填2; 360×2=720(三位数), 360×3=1080(四位数)→最小填3', 'jsj3_sx_v99', '["jsj3_sx","U2","p025","fill_06"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1016, '数学', '三年级', 'single', 2, '{"stem": "选择(1)：某小学报告厅有300个座位，安排（ ）年级同学观看木偶剧比较合适。四年级6个班每班48人，五年级6个班每班52人，六年级7个班每班46人。A. 四  B. 五  C. 六  D. 不确定"}', 'A', '四年级 6×48=288≤300; 五年级 6×52=312>300; 六年级 7×46=322>300', 'jsj3_sx_v99', '["jsj3_sx","U2","p026","choice_01"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1016, '数学', '三年级', 'single', 2, '{"stem": "选择(2)：3□8×6为三位数乘一位数的算式，下面四个数中，（ ）可能是它的得数。A. 228  B. 2208  C. 1900  D. 3048"}', 'B', '3□8范围308-398, 308×6=1848, 398×6=2388, 积在1848-2388间; 个位8×6=48→个位为8; 只有2208符合', 'jsj3_sx_v99', '["jsj3_sx","U2","p026","choice_02"]', 1, NULL);
