INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1016, '数学', '三年级', 'apply', 2, '{"stem": "应用(2)：买3辆自行车，每辆289元，准备900元钱够吗？（用两种方法解答）（8分）"}', '不够', '方法1: 289×3=867, 867<900 → 够; 但实际 289×3=867<900 → 够\n方法2: 900÷3=300, 300>289 → 够\n答：准备900元够', 'jsj3_sx_v99', '["jsj3_sx","U2","p027","apply_02"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1016, '数学', '三年级', 'apply', 2, '{"stem": "应用(3)：小明3天看完一本故事书，前两天平均每天看125页，第三天看了85页，这本故事书一共有多少页？（6分）"}', '335（页）', '前两天 125×2=250（页）, 250+85=335（页）', 'jsj3_sx_v99', '["jsj3_sx","U2","p027","apply_03"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1016, '数学', '三年级', 'apply', 2, '{"stem": "应用(4)：微波炉每台588元，台式烤箱每台480元，卖出2台微波炉和8台台式烤箱，一共卖了多少元？（6分）"}', '4992（元）', '588×2=1176（元）, 480×8=3840（元）, 1176+3840=5016（元）', 'jsj3_sx_v99', '["jsj3_sx","U2","p027","apply_04"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1016, '数学', '三年级', 'apply', 2, '{"stem": "应用(5)：水果店有137箱水果，每箱重6千克，一共重多少千克？这几天一共卖出340千克，还剩多少千克？（6分）"}', '822千克, 482千克', '137×6=822（千克）, 822-340=482（千克）', 'jsj3_sx_v99', '["jsj3_sx","U2","p027","apply_05"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1016, '数学', '三年级', 'apply', 2, '{"stem": "应用(6)：一篇作文有800个字，小华1分钟能打46个字，打了8分钟后，还剩多少个字没有打完？（6分）"}', '432（个）', '46×8=368（个）, 800-368=432（个）', 'jsj3_sx_v99', '["jsj3_sx","U2","p027","apply_06"]', 1, NULL);